    local function resolve_global(path)
        local cur = _G
        for part in path:gmatch("[^%.]+") do
            if type(cur) ~= "table" then return nil end
            cur = cur[part]
        end
        return cur
    end

    local total_verified_classes = 0
    local total_verified_methods = 0
    local total_verified_properties = 0

    local function verify_class_entry(t, entry)
        local reg = debug.getregistry()
        local mt = reg[entry.meta]
        t.assert_not_nil(mt, entry.name .. " metatable missing: " .. entry.meta)

        for i = 1, #entry.methods do
            local m = entry.methods[i]
            local fn = mt[m]
            t.assert_not_nil(fn, entry.name .. "." .. m .. " method missing on " .. entry.meta)
            t.assert_equal(type(fn), "function", entry.name .. "." .. m .. " must be function")
            total_verified_methods = total_verified_methods + 1
        end

        if entry.custom_indexer then
            -- Value types with custom C closure indexer (e.g. MyGUI.Colour, IntPoint)
            -- Verify property read and write on a live constructed instance
            local constructor = mt.new
            if not constructor and #entry.globals > 0 then
                local g = resolve_global(entry.globals[1])
                constructor = g and g.new
            end
            t.assert_not_nil(constructor, entry.name .. " has custom indexer but no constructor to verify properties")
            local inst = constructor()
            t.assert_not_nil(inst, entry.name .. " constructor returned nil")
            for i = 1, #entry.getters do
                local p = entry.getters[i]
                t.assert_not_nil(inst[p], entry.name .. "." .. p .. " property unreadable on instance")
                total_verified_properties = total_verified_properties + 1
            end
            for i = 1, #entry.setters do
                local p = entry.setters[i]
                inst[p] = 0
            end
        else
            local getters = mt.__getters
            for i = 1, #entry.getters do
                local p = entry.getters[i]
                t.assert_not_nil(getters and getters[p], entry.name .. "." .. p .. " getter missing on " .. entry.meta)
                total_verified_properties = total_verified_properties + 1
            end

            local setters = mt.__setters
            for i = 1, #entry.setters do
                local p = entry.setters[i]
                t.assert_not_nil(setters and setters[p], entry.name .. "." .. p .. " setter missing on " .. entry.meta)
            end
        end

        if entry.parent and entry.parent ~= "" then
            local parent_mt = reg[entry.parent]
            t.assert_not_nil(parent_mt, entry.name .. " parent metatable missing: " .. entry.parent)
            local child_meta = getmetatable(mt)
            local fallback = child_meta and child_meta.__index
            t.assert_equal(fallback, parent_mt, entry.name .. " inheritance link broken to " .. entry.parent)
        end

        for i = 1, #entry.globals do
            local g = entry.globals[i]
            t.assert_not_nil(resolve_global(g), entry.name .. " global table missing: " .. g)
        end

        total_verified_classes = total_verified_classes + 1
    end

