    ctx.test("template container instance factories and metatables", function(t)
        t.assert_not_nil(lektor, "lektor global table missing")
        local s_lek = lektor.new("string")
        t.assert_not_nil(s_lek, "lektor.new('string') failed")
        t.assert_equal(#s_lek, 0, "new string lektor size")
        local i_lek = lektor.new("int")
        t.assert_not_nil(i_lek, "lektor.new('int') failed")
        t.assert_equal(#i_lek, 0, "new int lektor size")
        local h_lek = lektor.new("hand")
        t.assert_not_nil(h_lek, "lektor.new('hand') failed")
        t.assert_equal(#h_lek, 0, "new hand lektor size")
    end)

